const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const clone=v=>typeof structuredClone==='function'?structuredClone(v):JSON.parse(JSON.stringify(v));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const clean=v=>v==null?'':String(v).trim(),normalMinutes=v=>Math.max(0,Math.floor(Number(v)||0));
const LEGACY_ORDER=['social','saa','president','tme','grammarIntro','variety','speeches','guestReport','intermission','topics','evaluation','reports','grammarReport','geComment','summary','adjourn'];
const DEFAULT_TIMES={social:14,saa:1,president:2,tme:8,grammarIntro:4,variety:15,guestReport:8,intermission:15,topics:16,geOpen:2,individualEval:6,reports:3,grammarReport:4,geComment:4,summary:2};
const TEMPLATE_LABELS={regular:'一般例會',joint:'聯合例會',keynote:'Keynote 例會',custom:'自由編排'};
const KIND_LABELS={role:'一般角色',speechGroup:'Prepared Speeches',keynote:'Keynote Speaker',activity:'休息／活動',group:'分組子列',text:'純文字'};
const ROLE_FIELDS=[['receptionist','Receptionist'],['saa','SAA'],['president','President'],['tme','Toastmaster'],['timer','Timer'],['ahCounter','Ah Counter'],['varietyMaster','Variety Master'],['topicsmaster','Topicsmaster'],['ge','General Evaluator'],['grammarian','Grammarian'],['evaluatorOfEvaluator','Evaluator of Evaluator'],['evaluatorOfTopicsmaster','Evaluator of Topicsmaster']];
const ROLE_LABELS=Object.fromEntries(ROLE_FIELDS);
const DB_NAME='sytc-agenda-builder',STORE='projects',LAST_KEY='sytc-agenda-last-project-v2';
let project,activeIndex=0,undoStack=[],redoStack=[],pendingRestore=null,saveTimer=null,resizeObserver=null,dialogResolve=null,meetingCommitPending=false;

function blankRoles(){return Object.fromEntries(ROLE_FIELDS.map(([k])=>[k,'']))}
function defaultHeader(template='regular'){const joint=template==='joint';return {customized:false,title:joint?'SYTC & CYBTC JOINT MEETING':'SHIN YING TOASTMASTERS CLUB',subtitle:joint?'Joint Meeting':'Since 2006　|　Club No. 974403　|　Area 4　|　Division H',schedule:'Regular Meeting: 7–9pm, 1st & 3rd Tuesday of every month',venue:'新營天居五樓會議室（新營區中山路）',online:'Zoom ID: 8911 1386 086　Password :907992',motto:'Learn Together; Empower Each Other.',mission:'We provide a supportive and positive learning experience in which members are empowered to develop communication and leadership skills.',logoAssetId:''}}
function makeSession(kind,title,duration=0,extra={}){return {id:uid(),kind,title,visible:true,duration:normalMinutes(duration),roleLabel:'',roleKey:'',assignee:'',legacyKey:'',roleKeys:[],subrows:[],...extra}}
function makeTemplateSessions(template,m={}){
 const t={...DEFAULT_TIMES,...(m.times||{})};if(template==='joint'){t.variety=10;t.topics=10;t.individualEval=16}
 const a=[
  makeSession('role','Equipment checkout & Social time',t.social,{legacyKey:'social',roleLabel:'Receptionist',roleKey:'receptionist'}),
  makeSession('role','SAA calls for opening',t.saa,{legacyKey:'saa',roleLabel:'SAA',roleKey:'saa'}),
  makeSession('role','Chair calls meeting to order',t.president,{legacyKey:'president',roleLabel:'President',roleKey:'president'}),
  makeSession('role','Toastmaster calls on meeting roles',t.tme,{legacyKey:'tme',roleLabel:'Toastmaster',roleKey:'tme',subrows:[{id:uid(),title:'Timer',roleLabel:'Timer',roleKey:'timer',assignee:'',duration:0,countsTime:false},{id:uid(),title:'Ah Counter',roleLabel:'Ah Counter',roleKey:'ahCounter',assignee:'',duration:0,countsTime:false}]}),
  makeSession('role','Word of the day',t.grammarIntro,{legacyKey:'grammarIntro',roleLabel:'Grammarian',roleKey:'grammarian'}),
  makeSession('role','Variety session',t.variety,{legacyKey:'variety',roleLabel:'Variety Master',roleKey:'varietyMaster'})
 ];
 if(template==='keynote')a.push(makeSession('keynote','Keynote Speech',0,{legacyKey:'keynote',roleLabel:'Keynote Speaker',evaluatorVisible:false}));
 a.push(makeSession('speechGroup','Manual speech session',0,{legacyKey:'speeches'}),makeSession('role','Officers’ report / Introducing guests',t.guestReport,{legacyKey:'guestReport',roleLabel:'President',roleKey:'president'}),makeSession('activity','Group photo / Intermission',t.intermission,{legacyKey:'intermission'}),makeSession('role','Table Topics Session (Each speech 1’–2’)',t.topics,{legacyKey:'topics',roleLabel:'Topicsmaster',roleKey:'topicsmaster'}),makeSession('group','Evaluation session (Each evaluation 2’–3’)',0,{legacyKey:'evaluation',roleLabel:'General Evaluator',roleKey:'ge',openMinutes:t.geOpen,individualMinutes:t.individualEval}),makeSession('role','Timer and Ah Counter’s reports',t.reports,{legacyKey:'reports',roleLabel:'Reports',roleKeys:['timer','ahCounter']}),makeSession('role','Grammarian’s report',t.grammarReport,{legacyKey:'grammarReport',roleLabel:'Grammarian',roleKey:'grammarian'}),makeSession('role','General Evaluator’s comment',t.geComment,{legacyKey:'geComment',roleLabel:'General Evaluator',roleKey:'ge'}),makeSession('role','Toastmaster wraps up',t.summary,{legacyKey:'summary',roleLabel:'Toastmaster',roleKey:'tme'}),makeSession('role','Chair adjourns meeting',0,{legacyKey:'adjourn',roleLabel:'President',roleKey:'president'}));return a;
}
function blankMeeting(number='',date=''){const m={id:uid(),schemaVersion:2,number,date:dateText(date),note:'English',theme:'',word:'',templateId:'regular',header:defaultHeader(),roles:blankRoles(),speakers:[],events:['',''],sessions:[],order:[...LEGACY_ORDER],times:{...DEFAULT_TIMES}};m.sessions=makeTemplateSessions('regular',m);return m}
function speechMinutes(duration,speaker){if(!clean(speaker))return 0;const nums=String(duration||'').match(/\d+/g);return nums?.length?Number(nums.at(-1))+1:8}
function makeSpeaker(data={}){return {id:data.id||uid(),name:clean(data.name),title:clean(data.title),level:clean(data.level),project:clean(data.project),duration:clean(data.duration),minutes:normalMinutes(data.minutes??speechMinutes(data.duration,data.name)),evaluator:clean(data.evaluator),sessionId:clean(data.sessionId)}}
function speakingSessions(m){return m.sessions.filter(s=>s.kind==='speechGroup'||s.kind==='keynote')}
function speakersFor(m,id){return m.speakers.filter(s=>s.sessionId===id)}
function normalizeSubrow(r={}){return {id:r.id||uid(),title:clean(r.title)||'子項目',roleLabel:clean(r.roleLabel),roleKey:clean(r.roleKey),assignee:clean(r.assignee),duration:normalMinutes(r.duration),countsTime:Boolean(r.countsTime)}}
function normalizeSession(s={}){const kinds=Object.keys(KIND_LABELS),x={...s};x.id=x.id||uid();x.kind=kinds.includes(x.kind)?x.kind:'role';x.title=clean(x.title)||KIND_LABELS[x.kind];x.visible=x.visible!==false;x.duration=normalMinutes(x.duration);x.roleLabel=clean(x.roleLabel);x.roleKey=clean(x.roleKey);x.assignee=clean(x.assignee);x.legacyKey=clean(x.legacyKey);x.roleKeys=Array.isArray(x.roleKeys)?x.roleKeys.map(clean).filter(Boolean):[];x.subrows=(x.subrows||[]).map(normalizeSubrow);x.openMinutes=normalMinutes(x.openMinutes);x.individualMinutes=normalMinutes(x.individualMinutes);x.evaluatorVisible=Boolean(x.evaluatorVisible);return x}
function legacyTimesFrom(m){const out={...DEFAULT_TIMES};for(const s of m.sessions){if(s.legacyKey&&!['evaluation','speeches','keynote'].includes(s.legacyKey))out[s.legacyKey]=normalMinutes(s.duration);if(s.legacyKey==='evaluation'){out.geOpen=normalMinutes(s.openMinutes);out.individualEval=normalMinutes(s.individualMinutes)}}return out}
function syncLegacy(m){m.order=m.sessions.map(s=>s.legacyKey).filter(k=>LEGACY_ORDER.includes(k));for(const k of LEGACY_ORDER)if(!m.order.includes(k))m.order.push(k);m.times=legacyTimesFrom(m)}
function normalizeMeeting(m){m.id=m.id||uid();m.schemaVersion=2;m.templateId=TEMPLATE_LABELS[m.templateId]?m.templateId:'regular';m.roles={...blankRoles(),...(m.roles||{})};m.events=[...(m.events||[]),'',''].slice(0,2);m.speakers=(m.speakers||[]).slice(0,5).map(makeSpeaker);m.header={...defaultHeader(m.templateId),...(m.header||{})};if(!Array.isArray(m.sessions)||!m.sessions.length){const order=(m.order||LEGACY_ORDER).filter(k=>LEGACY_ORDER.includes(k)),made=makeTemplateSessions(m.templateId,m),byKey=Object.fromEntries(made.map(s=>[s.legacyKey,s]));m.sessions=order.map(k=>byKey[k]).filter(Boolean);for(const s of made)if(!m.sessions.includes(s))m.sessions.push(s)}m.sessions=m.sessions.map(normalizeSession);let speech=m.sessions.find(s=>s.kind==='speechGroup');if(!speech){speech=makeSession('speechGroup','Manual speech session');m.sessions.push(speech)}const valid=new Set(speakingSessions(m).map(s=>s.id));for(const s of m.speakers)if(!valid.has(s.sessionId))s.sessionId=speech.id;syncLegacy(m);return m}
function normalizeProject(p){p.assets=p.assets||{};p.members=(p.members||[]).map(x=>typeof x==='string'?{name:x,active:true}:{name:clean(x.name),active:x.active!==false}).filter(x=>x.name);p.meetings=(p.meetings||[]).map(normalizeMeeting);p.baseMeetings=(p.baseMeetings||[]).map(normalizeMeeting);return p}
function demoProject(){const m=blankMeeting(452);m.date='2026-09-01';m.theme='Keep Going';m.word='agility';m.roles={receptionist:'Chin Chi Lai',saa:'Gina Wu',president:'Chin Chi Lai',tme:'Mark Weng',timer:'Alex Ho',ahCounter:'Mandy Lin',varietyMaster:'Darren Lin',topicsmaster:'Darren Lin',ge:'Camila Wu',grammarian:'Steve Huang',evaluatorOfEvaluator:'',evaluatorOfTopicsmaster:''};const sp=m.sessions.find(s=>s.kind==='speechGroup');m.speakers=[makeSpeaker({name:'Gina Wu',title:'Do We Really Need Three Meals a Day?',level:'EH L3-2',project:'Inspire your audience',duration:"5'-7'",minutes:8,evaluator:'Steve Huang',sessionId:sp.id}),makeSpeaker({name:'Camila Wu',title:'The Courage to Be Seen',level:'PM Level 5',project:'Prepare to speak professionally',duration:"18'-22'",minutes:23,evaluator:'Kimmy Chang',sessionId:sp.id}),makeSpeaker({name:'Sue Huang',minutes:0,sessionId:sp.id})];m.events=['9/29–9/30 SYTC 阿里山民宿 Outing',''];const n=blankMeeting(453);n.date='2026-09-15';n.templateId='keynote';n.sessions=makeTemplateSessions('keynote',n);n.theme='Learn Together';n.roles={receptionist:'Gina Wu',saa:'Alex Ho',president:'Chin Chi Lai',tme:'Camila Wu',timer:'Mandy Lin',ahCounter:'Steve Huang',varietyMaster:'Susan Su',topicsmaster:'Sunia Huang',ge:'Darren Lin',grammarian:'Mark Weng',evaluatorOfEvaluator:'',evaluatorOfTopicsmaster:''};const key=n.sessions.find(s=>s.kind==='keynote');n.speakers=[makeSpeaker({name:'Susan Su',title:'The Next Step',level:'Keynote',project:'Leadership',duration:"18'-20'",minutes:20,sessionId:key.id})];const names=['TBA','Alex Ho','Camila Wu','Chin Chi Lai','Darren Lin','Mandy Lin','Gina Wu','Steve Huang','Mark Weng','Susan Su','Sunia Huang','Sue Huang','Watchman Chen','Kimmy Chang'];return normalizeProject({id:'demo-project-v2',fileName:'示範資料',assets:{},members:names.map(name=>({name,active:true})),meetings:[m,n],baseMeetings:clone([m,n]),updatedAt:Date.now()})}

function activeMeeting(){return project.meetings[activeIndex]||project.meetings[0]}
function meetingNumber(m){const n=Number(m?.number);return Number.isInteger(n)&&n>0?n:Infinity}
function orderedMeetings(){return [...project.meetings].sort((a,b)=>meetingNumber(a)-meetingNumber(b)||String(a.id).localeCompare(String(b.id)))}
function meetingByNumber(number){return project.meetings.find(m=>meetingNumber(m)===Number(number))}
function nextScheduledMeeting(m=activeMeeting()){const n=meetingNumber(m);return orderedMeetings().find(x=>meetingNumber(x)>n)||null}
function selectFirstMeeting(){const first=orderedMeetings()[0];activeIndex=Math.max(0,project.meetings.findIndex(m=>m.id===first?.id))}
function snapshot(){return JSON.stringify({project,activeIndex})}
function restoreSnapshot(raw){const x=JSON.parse(raw);project=normalizeProject(x.project);activeIndex=Math.min(x.activeIndex,project.meetings.length-1);renderAll();queueSave()}
function applyChange(fn){undoStack.push(snapshot());if(undoStack.length>60)undoStack.shift();redoStack=[];fn();normalizeMeeting(activeMeeting());project.updatedAt=Date.now();renderAll();queueSave()}
function undo(){if(!undoStack.length)return;redoStack.push(snapshot());restoreSnapshot(undoStack.pop())}
function redo(){if(!redoStack.length)return;undoStack.push(snapshot());restoreSnapshot(redoStack.pop())}
function clock(mins){const h=Math.floor(mins/60)%24,m=mins%60;return h+':'+String(m).padStart(2,'0')}
function sessionDuration(m,s){if(['speechGroup','keynote'].includes(s.kind))return speakersFor(m,s.id).reduce((n,x)=>n+normalMinutes(x.minutes),0);if(s.legacyKey==='evaluation')return normalMinutes(s.openMinutes)+normalMinutes(s.individualMinutes);return normalMinutes(s.duration)+s.subrows.filter(x=>x.countsTime).reduce((n,x)=>n+normalMinutes(x.duration),0)}
function calculateTimes(m){let current=405;const starts={},speakerStarts={};for(const s of m.sessions.filter(x=>x.visible)){starts[s.id]=current;if(['speechGroup','keynote'].includes(s.kind)){for(const p of speakersFor(m,s.id)){speakerStarts[p.id]=current;current+=normalMinutes(p.minutes)}}else current+=sessionDuration(m,s)}return {starts,speakerStarts,finish:current}}

function memberNames(){return project.members.filter(x=>x.active).map(x=>x.name).filter(Boolean).sort((a,b)=>a.localeCompare(b,'zh-Hant'))}
function memberOptions(value){const names=memberNames(),has=value&&names.includes(value);return (value&&!has?'<option value="'+esc(value)+'">'+esc(value)+'（自訂）</option>':'')+'<option value="">待安排</option>'+names.map(n=>'<option value="'+esc(n)+'" '+(n===value?'selected':'')+'>'+esc(n)+'</option>').join('')+'<option value="__custom__">＋ 自行輸入名字…</option>'}
function getPerson(m,path){const [type,a,b]=path.split(':');if(type==='role')return m.roles[a]||'';if(type==='speaker')return m.speakers.find(x=>x.id===a)?.[b]||'';if(type==='session')return m.sessions.find(x=>x.id===a)?.assignee||'';return''}
function setPerson(m,path,value){const [type,a,b]=path.split(':');if(type==='role')m.roles[a]=value;else if(type==='speaker'){const s=m.speakers.find(x=>x.id===a);if(s)s[b]=value}else if(type==='session'){const s=m.sessions.find(x=>x.id===a);if(s)s.assignee=value}}
function personControl(path,label,value){return '<div class="person-drop" data-person-path="'+esc(path)+'"><div class="role-title"><span>'+esc(label)+'</span><span>可拖入</span></div>'+(value?'<div class="person-chip" data-person="'+esc(value)+'" data-source-path="'+esc(path)+'"><span class="grip">⠿</span>'+esc(value)+'</div>':'')+'<div class="person-line"><select onchange="personSelected(this)" data-path="'+esc(path)+'">'+memberOptions(value)+'</select><button type="button" onclick="customPerson(\''+esc(path)+'\')">＋</button></div></div>'}
function personSelected(el){let value=el.value;if(value==='__custom__'){customPerson(el.dataset.path);return}applyChange(()=>setPerson(activeMeeting(),el.dataset.path,value))}
function customPerson(path){const value=clean(prompt('輸入姓名：',''));if(!value){renderAll();return}applyChange(()=>{setPerson(activeMeeting(),path,value);if(!project.members.some(x=>x.name.toLowerCase()===value.toLowerCase())&&confirm('要把「'+value+'」加入人員下拉清單嗎？'))project.members.push({name:value,active:true})})}

function fieldInput(label,key,value,type='text',wide=false){return '<div class="field '+(wide?'wide':'')+'"><label>'+esc(label)+'</label><input type="'+type+'" value="'+esc(value)+'" onchange="meetingField(\''+key+'\',this.value)"></div>'}
function readonlyField(label,value){return '<div class="field"><label>'+esc(label)+'</label><input class="readonly-number" value="'+esc(value)+'" readonly></div>'}
function eventInput(i,value){return '<div class="field"><label>活動 '+(i+1)+'</label><textarea onchange="eventField('+i+',this.value)">'+esc(value)+'</textarea></div>'}
function textField(s,key,label){return '<div class="field"><label>'+label+'</label><input value="'+esc(s[key])+'" onchange="speakerField(\''+s.id+'\',\''+key+'\',this.value)"></div>'}
function sessionSelect(s,m){return '<div class="field"><label>Agenda Session</label><select onchange="speakerSession(\''+s.id+'\',this.value)">'+speakingSessions(m).map(x=>'<option value="'+x.id+'" '+(x.id===s.sessionId?'selected':'')+'>'+esc(x.title)+'（'+esc(KIND_LABELS[x.kind])+'）</option>').join('')+'</select></div>'}
function speakerEditor(s,i,m){const session=m.sessions.find(x=>x.id===s.sessionId),showEvaluator=session?.kind!=='keynote'||session.evaluatorVisible;return '<article class="speaker-card"><div class="speaker-head"><b>Speaker #'+(i+1)+(session?.kind==='keynote'?' · Keynote':'')+'</b><button class="btn btn-danger" type="button" onclick="removeSpeaker(\''+s.id+'\')">刪除 Speaker</button></div><div class="speaker-fields">'+personControl('speaker:'+s.id+':name','Speaker',s.name)+textField(s,'title','Speech Title')+textField(s,'level','Level')+textField(s,'project','Project')+textField(s,'duration','演講時間範圍')+'<div class="field"><label>Agenda 分鐘</label><input type="number" min="0" step="1" value="'+normalMinutes(s.minutes)+'" oninput="speakerMinutes(\''+s.id+'\',this.value)"></div>'+sessionSelect(s,m)+(showEvaluator?personControl('speaker:'+s.id+':evaluator','Evaluator',s.evaluator):'<div class="field evaluator-hidden"><label>Evaluator</label><span>此 Keynote Session 已隱藏</span></div>')+'</div></article>'}
function headerField(key,label,value,wide=false){return '<div class="field '+(wide?'wide':'')+'"><label>'+esc(label)+'</label><input value="'+esc(value)+'" onchange="setHeaderField(\''+key+'\',this.value)"></div>'}
function headerEditor(m){const asset=m.header.logoAssetId&&project.assets[m.header.logoAssetId];return '<details class="advanced-box"><summary>Agenda 抬頭與活動資訊</summary><div class="fields header-fields">'+headerField('title','活動／Club 名稱',m.header.title,true)+headerField('subtitle','副標題／共同主辦',m.header.subtitle,true)+headerField('schedule','例會資訊',m.header.schedule,true)+headerField('venue','場地',m.header.venue,true)+headerField('online','Zoom／線上資訊',m.header.online,true)+headerField('motto','標語',m.header.motto,true)+headerField('mission','Club Mission',m.header.mission,true)+'</div><div class="logo-tools"><span>'+(asset?'目前 Logo：'+esc(asset.name):'目前使用內建 Logo')+'</span><label class="btn">上傳 PNG／JPEG<input type="file" accept="image/png,image/jpeg" hidden onchange="uploadHeaderLogo(this)"></label>'+(asset?'<button class="btn" type="button" onclick="clearHeaderLogo()">改回內建 Logo</button>':'')+'</div></details>'}
function sessionCard(s,i,m){
 const person=s.roleKey||s.roleKeys.length?'<div class="field"><label>人員來源</label><span class="source-note">'+esc(s.roleKeys.length?s.roleKeys.map(k=>ROLE_LABELS[k]||k).join('、'):ROLE_LABELS[s.roleKey]||s.roleKey)+'</span></div>':personControl('session:'+s.id,s.roleLabel||'負責人',s.assignee);
 const roleEditor=['role','group'].includes(s.kind)?'<div class="field"><label>角色名稱</label><input value="'+esc(s.roleLabel)+'" onchange="sessionField(\''+s.id+'\',\'roleLabel\',this.value)"></div>'+person:'';
 const evalToggle=s.kind==='keynote'?'<label class="check-line"><input type="checkbox" '+(s.evaluatorVisible?'checked':'')+' onchange="sessionBoolean(\''+s.id+'\',\'evaluatorVisible\',this.checked)"> 顯示 Evaluator</label>':'';
 const children=s.kind==='group'?'<div class="subrow-list">'+s.subrows.map(r=>'<div class="subrow"><input value="'+esc(r.title)+'" onchange="subrowField(\''+s.id+'\',\''+r.id+'\',\'title\',this.value)" aria-label="子列名稱"><input value="'+esc(r.roleLabel)+'" onchange="subrowField(\''+s.id+'\',\''+r.id+'\',\'roleLabel\',this.value)" placeholder="角色"><select onchange="subrowPerson(\''+s.id+'\',\''+r.id+'\',this.value)">'+memberOptions(r.roleKey?m.roles[r.roleKey]:r.assignee)+'</select><label><input type="checkbox" '+(r.countsTime?'checked':'')+' onchange="subrowToggle(\''+s.id+'\',\''+r.id+'\',this.checked)">計時</label><input type="number" min="0" value="'+r.duration+'" onchange="subrowField(\''+s.id+'\',\''+r.id+'\',\'duration\',this.value)" aria-label="子列分鐘"><button type="button" onclick="removeSubrow(\''+s.id+'\',\''+r.id+'\')">×</button></div>').join('')+'<button class="btn compact" type="button" onclick="addSubrow(\''+s.id+'\')">＋ 子列</button></div>':'';
 return '<article class="session-builder-card" data-session-id="'+s.id+'"><div class="session-builder-head"><span class="drag-handle">⠿</span><div><b>'+esc(s.title)+'</b><small>'+esc(KIND_LABELS[s.kind])+' · '+sessionDuration(m,s)+' 分</small></div><label class="visibility-toggle"><input type="checkbox" '+(s.visible?'checked':'')+' onchange="sessionBoolean(\''+s.id+'\',\'visible\',this.checked)">顯示</label><div class="session-buttons"><button type="button" onclick="moveSession(\''+s.id+'\',-1)" '+(i===0?'disabled':'')+'>↑</button><button type="button" onclick="moveSession(\''+s.id+'\',1)" '+(i===m.sessions.length-1?'disabled':'')+'>↓</button><button type="button" onclick="duplicateSession(\''+s.id+'\')">⧉</button><button type="button" onclick="removeSession(\''+s.id+'\')">×</button></div></div><div class="session-edit-grid"><div class="field"><label>Session 名稱</label><input value="'+esc(s.title)+'" onchange="sessionField(\''+s.id+'\',\'title\',this.value)"></div>'+(!['speechGroup','keynote'].includes(s.kind)&&s.legacyKey!=='evaluation'?'<div class="field"><label>分鐘</label><input type="number" min="0" step="1" value="'+s.duration+'" onchange="sessionField(\''+s.id+'\',\'duration\',this.value)"></div>':'')+roleEditor+evalToggle+'</div>'+children+'</article>';
}
function renderEditor(){
 const m=activeMeeting(),warnings=collectWarnings(m),roles=ROLE_FIELDS.map(([k,l])=>personControl('role:'+k,l,m.roles[k])).join(''),members=project.members.map((x,i)=>x.active?'<span class="member-token" data-person="'+esc(x.name)+'">⠿ '+esc(x.name)+' <button type="button" onclick="editMember('+i+')">✎</button></span>':'').join(''),speakers=m.speakers.map((s,i)=>speakerEditor(s,i,m)).join('')||'<div class="placeholder">目前沒有 Speaker，請按下方按鈕新增。</div>',sessions=m.sessions.map((s,i)=>sessionCard(s,i,m)).join('');
 $('#editorContent').innerHTML='<div class="editor-head"><div><h2>Meeting '+esc(m.number||'未編號')+' 工作安排</h2><p>先用範本快速開始，需要時再展開自由編排。</p></div><span class="save-state '+(warnings.length?'warn':'')+'">'+(warnings.length?warnings.length+' 項提醒':'資料完整')+'</span></div><div class="editor-grid">'+
 '<section class="card"><h3>場次資料 <small>Meeting Number 由左側切換</small></h3><div class="fields">'+readonlyField('Meeting Number',m.number)+fieldInput('日期','date',m.date,'date')+fieldInput('備註／語言','note',m.note)+fieldInput('Meeting Theme','theme',m.theme)+fieldInput('Word of the Day','word',m.word,'text',true)+'</div><div class="template-picker"><label>Agenda 範本</label><select id="templateSelect">'+Object.entries(TEMPLATE_LABELS).map(([k,v])=>'<option value="'+k+'" '+(k===m.templateId?'selected':'')+' '+(k==='custom'?'disabled':'')+'>'+v+'</option>').join('')+'</select><button class="btn" type="button" onclick="applySelectedTemplate()">套用範本</button></div>'+headerEditor(m)+'</section>'+
 '<section class="card"><h3>人員名單 <small>可拖到角色欄位</small></h3><div class="member-tools"><input id="newMemberName" placeholder="輸入新會員或來賓姓名"><button class="btn" type="button" onclick="addMember()">＋新增</button></div><div class="member-pool" id="memberPool">'+members+'</div></section>'+
 '<section class="card full"><h3>例會角色 <small>維持舊 Excel 欄位相容</small></h3><div class="role-grid">'+roles+'</div></section>'+
 '<section class="card full"><h3>Speakers <small>'+m.speakers.length+' / 5 位</small></h3><div class="speaker-list">'+speakers+'</div><button class="btn btn-primary add-speaker" type="button" onclick="addSpeaker()" '+(m.speakers.length>=5?'disabled':'')+'>＋ 新增 Speaker</button></section>'+
 '<section class="card full"><h3>自由編排 <small>拖曳、新增、隱藏或自訂 Session</small></h3><div class="add-session-bar"><select id="newSessionKind">'+Object.entries(KIND_LABELS).map(([k,v])=>'<option value="'+k+'">'+esc(v)+'</option>').join('')+'</select><button class="btn btn-primary" type="button" onclick="addSessionFromPicker()">＋ 新增 Session</button></div><div class="session-builder" id="sessionList">'+sessions+'</div></section>'+
 '<section class="card"><h3>Upcoming Events</h3><div class="future-grid">'+eventInput(0,m.events[0])+eventInput(1,m.events[1])+'</div></section><section class="card"><h3>檢查提醒 <small>不阻擋自由編排</small></h3><div class="warning-box '+(warnings.length?'show':'')+'">'+(warnings.map(x=>'• '+esc(x)).join('<br>')||'目前沒有提醒')+'</div></section></div>';initSortables();
}

function meetingField(key,value){applyChange(()=>activeMeeting()[key]=clean(value))}
function eventField(i,value){applyChange(()=>activeMeeting().events[i]=clean(value))}
function speakerField(id,key,value){applyChange(()=>{const s=activeMeeting().speakers.find(x=>x.id===id);if(!s)return;s[key]=clean(value);if(key==='duration'&&!s.minutes)s.minutes=speechMinutes(value,s.name)})}
function speakerMinutes(id,value){const s=activeMeeting().speakers.find(x=>x.id===id),next=normalMinutes(value);if(!s||s.minutes===next)return;s.minutes=next;project.updatedAt=Date.now();renderPreview(true);queueSave()}
function speakerSession(id,sessionId){applyChange(()=>{const s=activeMeeting().speakers.find(x=>x.id===id);if(s)s.sessionId=sessionId})}
function sessionField(id,key,value){applyChange(()=>{const s=activeMeeting().sessions.find(x=>x.id===id);if(s)s[key]=key==='duration'?normalMinutes(value):clean(value);activeMeeting().templateId='custom'})}
function sessionBoolean(id,key,value){applyChange(()=>{const s=activeMeeting().sessions.find(x=>x.id===id);if(s)s[key]=Boolean(value);activeMeeting().templateId='custom'})}
function setSessionMinutes(id,value,key='duration'){const s=activeMeeting().sessions.find(x=>x.id===id);if(!s)return;s[key]=normalMinutes(value);activeMeeting().templateId='custom';project.updatedAt=Date.now();renderPreview(true);queueSave()}
function setHeaderField(key,value){applyChange(()=>{activeMeeting().header[key]=clean(value);activeMeeting().header.customized=true})}
async function uploadHeaderLogo(input){const file=input.files?.[0];if(!file)return;if(!/^image\/(png|jpeg)$/.test(file.type)||file.size>1024*1024){toast('Logo 請使用 1MB 以下 PNG 或 JPEG','error');return}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}),id=uid();applyChange(()=>{project.assets[id]={id,name:file.name,type:file.type,data};activeMeeting().header.logoAssetId=id;activeMeeting().header.customized=true})}
function clearHeaderLogo(){applyChange(()=>{activeMeeting().header.logoAssetId='';activeMeeting().header.customized=true})}
async function applySelectedTemplate(){const id=$('#templateSelect').value,m=activeMeeting();if(id===m.templateId)return;if(!await confirmAction('套用 '+TEMPLATE_LABELS[id],'將重新排列標準流程；人員、Speaker 與自訂 Session 會保留。')){renderAll();return}applyChange(()=>{const custom=m.sessions.filter(s=>!s.legacyKey),oldKinds=new Map(m.sessions.map(s=>[s.id,s.kind])),next=makeTemplateSessions(id,m),speech=next.find(s=>s.kind==='speechGroup'),key=next.find(s=>s.kind==='keynote');m.sessions=[...next,...custom];for(const p of m.speakers){const kind=oldKinds.get(p.sessionId);if(kind==='keynote'&&key)p.sessionId=key.id;else if(!custom.some(s=>s.id===p.sessionId))p.sessionId=speech.id}m.templateId=id;if(!m.header.customized)m.header=defaultHeader(id)})}
function addSessionFromPicker(){const kind=$('#newSessionKind').value,titles={role:'Custom Agenda Item',speechGroup:'Prepared Speeches',keynote:'Keynote Speech',activity:'Break / Activity',group:'Custom Session',text:'Announcement'},s=makeSession(kind,titles[kind]||'Custom Session',kind==='activity'?5:0,{roleLabel:kind==='role'?'Role':'',evaluatorVisible:false});applyChange(()=>{activeMeeting().sessions.splice(Math.max(0,activeMeeting().sessions.length-1),0,s);activeMeeting().templateId='custom'})}
function duplicateSession(id){applyChange(()=>{const m=activeMeeting(),i=m.sessions.findIndex(x=>x.id===id);if(i<0)return;const c=clone(m.sessions[i]);c.id=uid();c.legacyKey='';c.title+='（複製）';c.subrows=(c.subrows||[]).map(r=>({...r,id:uid()}));m.sessions.splice(i+1,0,c);m.templateId='custom'})}
async function removeSession(id){const m=activeMeeting(),s=m.sessions.find(x=>x.id===id);if(!s)return;if(!await confirmAction('刪除 Session','將刪除「'+s.title+'」的版面；Speaker 資料會移到其他演講 Session。'))return;applyChange(()=>{const target=m.sessions.find(x=>x.id!==id&&x.kind==='speechGroup');for(const p of m.speakers)if(p.sessionId===id)p.sessionId=target?.id||'';m.sessions=m.sessions.filter(x=>x.id!==id);m.templateId='custom'})}
function moveSession(id,delta){applyChange(()=>{const m=activeMeeting(),i=m.sessions.findIndex(x=>x.id===id),j=Math.max(0,Math.min(m.sessions.length-1,i+delta));if(i<0||i===j)return;const [s]=m.sessions.splice(i,1);m.sessions.splice(j,0,s);m.templateId='custom'})}
function addSubrow(id){applyChange(()=>{const s=activeMeeting().sessions.find(x=>x.id===id);if(s)s.subrows.push(normalizeSubrow());activeMeeting().templateId='custom'})}
function removeSubrow(id,rowId){applyChange(()=>{const s=activeMeeting().sessions.find(x=>x.id===id);if(s)s.subrows=s.subrows.filter(x=>x.id!==rowId);activeMeeting().templateId='custom'})}
function subrowField(id,rowId,key,value){applyChange(()=>{const r=activeMeeting().sessions.find(x=>x.id===id)?.subrows.find(x=>x.id===rowId);if(r)r[key]=key==='duration'?normalMinutes(value):clean(value);activeMeeting().templateId='custom'})}
function subrowToggle(id,rowId,value){applyChange(()=>{const r=activeMeeting().sessions.find(x=>x.id===id)?.subrows.find(x=>x.id===rowId);if(r)r.countsTime=Boolean(value);activeMeeting().templateId='custom'})}
function subrowPerson(id,rowId,value){if(value==='__custom__'){const v=clean(prompt('輸入姓名：',''));if(!v){renderAll();return}value=v}applyChange(()=>{const r=activeMeeting().sessions.find(x=>x.id===id)?.subrows.find(x=>x.id===rowId);if(r){r.roleKey='';r.assignee=value}})}

function addMember(){const input=$('#newMemberName'),name=clean(input.value);if(!name)return;if(project.members.some(x=>x.name.toLowerCase()===name.toLowerCase())){toast('這個姓名已在人員名單中','error');return}applyChange(()=>project.members.push({name,active:true}))}
function editMember(index){const member=project.members[index];if(!member||!member.active)return;const next=clean(prompt('修改姓名；留空將停用此人：',member.name));if(!next){if(confirm('停用「'+member.name+'」？歷史安排會保留。'))applyChange(()=>member.active=false);return}if(next===member.name)return;if(project.members.some(x=>x!==member&&x.name.toLowerCase()===next.toLowerCase())){toast('這個姓名已存在','error');return}applyChange(()=>{for(const m of project.meetings){for(const k of Object.keys(m.roles))if(m.roles[k]===member.name)m.roles[k]=next;for(const s of m.speakers){if(s.name===member.name)s.name=next;if(s.evaluator===member.name)s.evaluator=next}for(const s of m.sessions){if(s.assignee===member.name)s.assignee=next;for(const r of s.subrows)if(r.assignee===member.name)r.assignee=next}}member.name=next})}
function addSpeaker(){const m=activeMeeting();if(m.speakers.length>=5){toast('為維持舊 Excel 相容，每場最多 5 位 Speaker','error');return}const session=m.sessions.find(x=>x.kind==='speechGroup')||speakingSessions(m)[0];applyChange(()=>m.speakers.push(makeSpeaker({sessionId:session?.id||''})))}
async function removeSpeaker(id){if(!await confirmAction('刪除 Speaker','將刪除這位 Speaker、演講資料及 Evaluator。'))return;applyChange(()=>{activeMeeting().speakers=activeMeeting().speakers.filter(x=>x.id!==id)})}
function collectWarnings(m){const out=[];for(const p of m.speakers){if(!p.name)out.push('Speaker 尚未安排講者');const s=m.sessions.find(x=>x.id===p.sessionId);if(!s)out.push((p.name||'Speaker')+' 尚未指定 Agenda Session');if(s?.kind!=='keynote'&&p.name&&!p.evaluator)out.push(p.name+' 尚未安排 Evaluator')}for(const s of m.sessions.filter(x=>x.visible&&x.kind==='keynote'))if(!speakersFor(m,s.id).length)out.push('Keynote Session 尚未安排 Speaker');const last=m.sessions.filter(x=>x.visible).at(-1);if(last?.legacyKey!=='adjourn')out.push('Chair adjourns meeting 目前不是最後一個 Session');if(!m.date)out.push('尚未填寫日期');if(!m.number)out.push('尚未填寫 Meeting Number');const assigned=[...Object.values(m.roles),...m.speakers.flatMap(s=>[s.name,s.evaluator])].filter(Boolean),counts={};assigned.filter(x=>x.toUpperCase()!=='TBA').forEach(x=>counts[x]=(counts[x]||0)+1);const dup=Object.entries(counts).filter(([,n])=>n>1).map(([n,c])=>n+'（'+c+'項）');if(dup.length)out.push('同一人有多個任務：'+dup.join('、'));return out}
function initSortables(){if(typeof Sortable==='undefined')return;const member=$('#memberPool');if(member)new Sortable(member,{group:{name:'people',pull:'clone',put:false},sort:false,animation:150});$$('.person-drop').forEach(el=>new Sortable(el,{group:'people',animation:150,onAdd(evt){const name=evt.item.dataset.person,path=el.dataset.personPath;evt.item.remove();applyChange(()=>setPerson(activeMeeting(),path,name))}}));const session=$('#sessionList');if(session)new Sortable(session,{animation:160,handle:'.drag-handle',delayOnTouchOnly:true,delay:120,onEnd(){const ids=$$('#sessionList .session-builder-card').map(x=>x.dataset.sessionId);applyChange(()=>{const m=activeMeeting(),byId=Object.fromEntries(m.sessions.map(s=>[s.id,s]));m.sessions=ids.map(id=>byId[id]).filter(Boolean);m.templateId='custom'})}})}

function sessionPerson(m,s){if(s.roleKeys?.length)return s.roleKeys.map(k=>m.roles[k]).filter(Boolean).join(', ');return s.roleKey?m.roles[s.roleKey]||'':s.assignee||''}
function subrowPersonValue(m,r){return r.roleKey?m.roles[r.roleKey]||'':r.assignee||''}
function agendaRow(time,label,role,name,target=''){return '<div class="agenda-row" '+(target?'data-session="'+esc(target)+'"':'')+'><span class="agenda-time">'+esc(time)+'</span><span>'+esc(label)+'</span><span class="agenda-role">'+esc(role)+'</span><span class="agenda-name">'+esc(name||'')+'</span></div>'}
function speechAgenda(s,i,start,target,kind='speechGroup'){const meta=[s.level,s.project].filter(Boolean).join(' · ');return '<div class="speech '+(kind==='keynote'?'keynote-speech':'')+'" data-session="'+esc(target)+'"><div class="speech-time">'+clock(start)+'</div><div class="speech-num">'+(kind==='keynote'?'★':i+1)+'</div><div class="speech-main"><div class="speech-detail"><b>'+esc(s.name||'待安排講者')+'</b><i>'+esc(s.title||'')+'</i></div><div class="speech-meta">'+esc(meta)+'</div></div><div class="speech-duration">'+esc(s.duration||'')+'</div></div>'}
function renderSession(m,s,t){
 const start=clock(t.starts[s.id]??405),person=sessionPerson(m,s);
 if(['speechGroup','keynote'].includes(s.kind)){const ps=speakersFor(m,s.id);let out='<div class="section-row '+(s.kind==='keynote'?'keynote-heading':'')+'" data-session="'+s.id+'"><span>'+start+'</span><span>'+esc(s.title)+'</span></div>';out+=ps.map((p,i)=>speechAgenda(p,i,t.speakerStarts[p.id],`speaker:${p.id}`,s.kind)).join('');if(!ps.length)out+=agendaRow('',s.kind==='keynote'?'Keynote Speaker 尚未安排':'目前沒有 Speaker','','',`speaker-empty:${s.id}`);return out}
 if(s.legacyKey==='tme'){let out=agendaRow(start,s.title,s.roleLabel,person,s.id);for(const r of s.subrows)out+=agendaRow('',r.title,r.roleLabel,subrowPersonValue(m,r),`subrow:${r.id}`);return out}
 if(s.legacyKey==='grammarIntro')return agendaRow(start,s.title+(m.word?' · '+m.word:''),s.roleLabel,person,s.id);
 if(s.legacyKey==='intermission')return '<div class="merge-row" data-session="'+s.id+'"><span>'+start+'</span><span>'+esc(s.title)+' ('+Math.max(0,s.duration-1)+' mins)</span></div>';
 if(s.legacyKey==='evaluation'){let out=agendaRow(start,s.title,s.roleLabel,person,s.id),ps=m.speakers.filter(p=>{const x=m.sessions.find(q=>q.id===p.sessionId);return x?.kind==='speechGroup'||(x?.kind==='keynote'&&x.evaluatorVisible)});out+=ps.map((p,i)=>agendaRow('',String(i+1),'Evaluator',p.evaluator,i===0?`evaluation:${s.id}`:'')).join('')||agendaRow('','Individual evaluations','Evaluator','待安排',`evaluation:${s.id}`);if(m.roles.evaluatorOfEvaluator)out+=agendaRow('','Evaluator of Evaluator','Evaluator',m.roles.evaluatorOfEvaluator);if(m.roles.evaluatorOfTopicsmaster)out+=agendaRow('','Evaluator of Topicsmaster','Evaluator',m.roles.evaluatorOfTopicsmaster);return out}
 if(s.kind==='text'||(s.kind==='activity'&&!s.roleLabel&&!person)){let out='<div class="merge-row" data-session="'+s.id+'"><span>'+start+'</span><span>'+esc(s.title)+'</span></div>';for(const r of s.subrows)out+=agendaRow('',r.title,r.roleLabel,subrowPersonValue(m,r),`subrow:${r.id}`);return out}
 let out=agendaRow(start,s.title,s.roleLabel,person,s.id);for(const r of s.subrows)out+=agendaRow('',r.title,r.roleLabel,subrowPersonValue(m,r),`subrow:${r.id}`);return out;
}
function headerHtml(m){const h=m.header,asset=h.logoAssetId&&project.assets[h.logoAssetId],src=asset?.data||'assets/xl/media/image1.png';return '<header class="club"><div class="club-logo '+(asset?'uploaded':'')+'"><img src="'+esc(src)+'" alt="Club logo"></div><div class="club-title"><h3>'+esc(h.title)+'</h3><p>'+esc(h.subtitle)+'</p></div></header><div class="strip"><span>'+esc(h.schedule)+'</span><span>Venue: '+esc(h.venue)+'</span></div><div class="strip motto"><span>'+esc(h.online)+'</span><strong>'+esc(h.motto)+'</strong></div>'}
function futureHtml(m){return '<section class="future"><h4>未來活動</h4><div>1. '+esc(m.events[0]||'')+'</div><div>2. '+esc(m.events[1]||'')+'</div></section>'}
function upcomingItems(m){const items=[['Toastmaster',m.roles.tme],['Receptionist',m.roles.receptionist],['General Evaluator',m.roles.ge],['Timer',m.roles.timer],['Variety Master',m.roles.varietyMaster],['Ah Counter',m.roles.ahCounter],['Topicsmaster',m.roles.topicsmaster],['Grammarian',m.roles.grammarian]];let speech=0,keynote=0;for(const p of m.speakers){const s=m.sessions.find(x=>x.id===p.sessionId);if(s?.kind==='keynote'){items.push(['Keynote Speaker #'+(++keynote),p.name]);if(s.evaluatorVisible)items.push(['Keynote Evaluator #'+keynote,p.evaluator])}else{items.push(['Speaker #'+(++speech),p.name]);items.push(['Evaluator #'+speech,p.evaluator])}}for(const s of m.sessions)if(!s.legacyKey&&s.kind==='role'&&sessionPerson(m,s))items.push([s.roleLabel||s.title,sessionPerson(m,s)]);return items}
function upcomingHtml(){const next=nextScheduledMeeting();if(!next)return '<section class="next-empty">尚未建立下一場預排</section>';const items=upcomingItems(next),half=Math.ceil(items.length/2),left=items.slice(0,half),right=items.slice(half),rows=Math.max(left.length,right.length),heading='Meeting '+esc(next.number)+'<small>'+esc(next.date||'日期未設定')+'</small>';let body='';for(let i=0;i<rows;i++)body+='<tr><td>'+esc(left[i]?.[0]||'')+'</td><td>'+esc(left[i]?.[1]||'')+'</td><td>'+esc(right[i]?.[0]||'')+'</td><td>'+esc(right[i]?.[1]||'')+'</td></tr>';return '<table class="next-roles"><thead><tr><th>Meeting Role</th><th>'+heading+'</th><th>Meeting Role</th><th>'+heading+'</th></tr></thead><tbody>'+body+'</tbody></table>'}
function renderPreview(preservePanel=false){const m=activeMeeting(),t=calculateTimes(m);$('#previewTitle').textContent='Meeting '+(m.number||'未編號')+' · '+(TEMPLATE_LABELS[m.templateId]||'自由編排');$('#sheet').innerHTML=headerHtml(m)+'<div class="agenda-body"><aside class="mission"><h4>Club Mission</h4><p>'+esc(m.header.mission)+'</p></aside><div class="agenda-grid"><div class="meta"><div>Date: <span>'+esc(m.date)+'</span></div><div>Meeting No. <span>'+esc(m.number)+'</span></div><div>Theme: <span>'+esc(m.theme)+'</span></div></div>'+m.sessions.filter(s=>s.visible).map(s=>renderSession(m,s,t)).join('')+'</div></div>'+futureHtml(m)+upcomingHtml();const overtime=t.finish-540;$('#previewStatus').textContent=overtime>0?'⚠ 預計超時 '+overtime+' 分鐘':'● 即時預覽';$('#previewStatus').style.background=overtime>0?'#fff0d4':'';if(!preservePanel)renderTimePanel(m,t);else{const warning=$('.time-warnings');if(warning)warning.innerHTML=overtime>0?'<div>⚠ 預計超時 '+overtime+' 分鐘（結束 '+clock(t.finish)+'）</div>':'';scheduleAlignment()}}
function renderMeetingSelector(){const ordered=orderedMeetings(),position=ordered.findIndex(m=>m.id===activeMeeting().id);$('#meetingNumberInput').value=activeMeeting().number||'';$('#meetingNumberList').innerHTML=ordered.map(m=>'<option value="'+esc(m.number)+'">Meeting '+esc(m.number)+' · '+esc(m.date||'未填日期')+'</option>').join('');$('#prevMeeting').disabled=position<=0;$('#nextMeeting').disabled=position<0||position===ordered.length-1;$('#deleteMeeting').disabled=project.meetings.length===1;$('#fileName').textContent=project.fileName||'工作安排'}
function controlInput(session,label,value,target,key='duration'){return '<label class="time-control" data-control-target="'+esc(target)+'"><b>'+esc(label)+'</b><input type="number" min="0" step="1" value="'+normalMinutes(value)+'" oninput="setSessionMinutes(\''+session.id+'\',this.value,\''+key+'\')"></label>'}
function renderTimePanel(m,t){let controls='';for(const s of m.sessions.filter(x=>x.visible)){if(['speechGroup','keynote'].includes(s.kind)){controls+=speakersFor(m,s.id).map((p,i)=>'<label class="time-control" data-control-target="speaker:'+p.id+'"><b>'+(s.kind==='keynote'?'Keynote':('演講者 '+(i+1)))+'</b><input type="number" min="0" step="1" value="'+normalMinutes(p.minutes)+'" oninput="speakerMinutes(\''+p.id+'\',this.value)"></label>').join('');continue}if(s.legacyKey==='evaluation'){controls+=controlInput(s,'GE 開場',s.openMinutes,s.id,'openMinutes')+controlInput(s,'個別講評',s.individualMinutes,'evaluation:'+s.id,'individualMinutes');continue}if(s.legacyKey==='adjourn')continue;controls+=controlInput(s,s.title,s.duration,s.id);for(const r of s.subrows.filter(x=>x.countsTime))controls+='<label class="time-control" data-control-target="subrow:'+r.id+'"><b>'+esc(r.title)+'</b><input type="number" min="0" step="1" value="'+r.duration+'" onchange="subrowField(\''+s.id+'\',\''+r.id+'\',\'duration\',this.value)"></label>'}const overtime=t.finish-540;$('#timePanel').style.height=$('#sheet').offsetHeight+'px';$('#timePanel').innerHTML='<details open><summary>時間控制器 <small>分鐘</small></summary><div class="start-anchor"><b>固定起點</b><strong>6:45</strong></div><div class="time-help">自由增減或拖曳 Session，後續時間立即重算</div>'+controls+'<div class="time-warnings">'+(overtime>0?'<div>⚠ 預計超時 '+overtime+' 分鐘（結束 '+clock(t.finish)+'）</div>':'')+'</div></details>';observeAlignment()}
function observeAlignment(){resizeObserver?.disconnect();if(window.ResizeObserver){resizeObserver=new ResizeObserver(scheduleAlignment);resizeObserver.observe($('#sheet'))}scheduleAlignment()}
function scheduleAlignment(){requestAnimationFrame(syncAlignment)}
function syncAlignment(){const sheet=$('#sheet'),panel=$('#timePanel');if(!sheet||!panel)return;panel.style.height=sheet.offsetHeight+'px';const sr=sheet.getBoundingClientRect();$$('.time-control').forEach(c=>{const target=[...sheet.querySelectorAll('[data-session]')].find(x=>x.dataset.session===c.dataset.controlTarget);if(!target)return;const tr=target.getBoundingClientRect();c.style.top=(tr.top-sr.top-panel.clientTop)+'px';c.style.height=tr.height+'px'})}
function renderAll(){normalizeProject(project);renderMeetingSelector();renderEditor();renderPreview();$('#undoBtn').disabled=!undoStack.length;$('#redoBtn').disabled=!redoStack.length}

function dateText(v){if(!v)return'';const d=parseLocalDate(v);return d?formatLocalDate(d):clean(v).replace(/\//g,'-')}
function parseLocalDate(v){const m=clean(v).match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})$/);if(!m)return null;const d=new Date(+m[1],+m[2]-1,+m[3]);return Number.isNaN(d.getTime())?null:d}
function formatLocalDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function isClubMeetingDate(d){return d.getDay()===2&&[1,3].includes(Math.ceil(d.getDate()/7))}
function stepClubMeetingDate(value,direction=1){let d=parseLocalDate(value)||new Date();do d.setDate(d.getDate()+direction);while(!isClubMeetingDate(d));return formatLocalDate(d)}
function inferredMeetingDate(number){const known=project.meetings.filter(m=>m.number&&m.date&&parseLocalDate(m.date)).sort((a,b)=>Math.abs(a.number-number)-Math.abs(b.number-number))[0];if(!known)return'';let date=known.date,n=known.number;while(n!==number){date=stepClubMeetingDate(date,number>n?1:-1);n+=number>n?1:-1}return date}

function detectLegacyTemplates(wb,meetings){for(const [name,template] of [['SYTC agenda','regular'],['SYTC & CYBTC agenda ','joint']]){const sheet=wb.Sheets[name];if(!sheet)continue;const number=Number(sheet.L8?.v||sheet.K8?.v);const m=meetings.find(x=>x.number===number);if(m){m.templateId=template;m.header=defaultHeader(template);m.sessions=makeTemplateSessions(template,m)}}}
function readAssets(wb){const ws=wb.Sheets['Agenda資源'];if(!ws)return{};const rows=XLSX.utils.sheet_to_json(ws,{defval:''}),groups={};for(const r of rows){if(!r.AssetID||!r.Chunk)continue;(groups[r.AssetID]??={name:r.Name||'logo',mime:r.Mime||'image/png',parts:[]}).parts[Number(r.ChunkIndex)||0]=r.Chunk}const out={};for(const [id,a] of Object.entries(groups))out[id]={id,name:a.name,mime:a.mime,data:'data:'+a.mime+';base64,'+a.parts.join('')};return out}
function applyAgendaSettings(wb,meetings){const ws=wb.Sheets['Agenda設定'];if(!ws)return;const rows=XLSX.utils.sheet_to_json(ws,{defval:''});for(const row of rows){const m=meetings.find(x=>x.number===Number(row.MeetingNumber));if(!m)continue;let hasSessions=false;try{if(row.HeaderJSON)m.header={...m.header,...JSON.parse(row.HeaderJSON)}}catch{}try{if(row.SessionsJSON){m.sessions=JSON.parse(row.SessionsJSON);hasSessions=true}}catch{}if(row.TemplateID)m.templateId=row.TemplateID;if(!hasSessions){try{if(row.SessionOrder)m.order=JSON.parse(row.SessionOrder)}catch{}try{if(row.TimeSettings)m.times={...m.times,...JSON.parse(row.TimeSettings)}}catch{}if(row.SessionOrder||row.TimeSettings)m.sessions=[]}try{const mins=JSON.parse(row.SpeakerMinutes||'[]');m.speakers.forEach((s,i)=>{if(mins[i]!=null)s.minutes=normalMinutes(mins[i])})}catch{}try{const map=JSON.parse(row.SpeakerSessionMap||'[]');m.speakers.forEach((s,i)=>{if(map[i])s.sessionId=map[i]})}catch{}normalizeMeeting(m)}}
function assignedNames(ws,row){return [ws[`G${row}`]?.v,ws[`K${row}`]?.v,ws[`O${row}`]?.v,ws[`S${row}`]?.v,ws[`W${row}`]?.v].map(clean).filter(Boolean)}
function parseWorkbook(buffer,fileName,id){const wb=XLSX.read(buffer,{type:'array',cellDates:true}),ws=wb.Sheets['Assignment for Agenda(工作安排)'];if(!ws)throw new Error('找不到「Assignment for Agenda(工作安排)」工作表');const range=XLSX.utils.decode_range(ws['!ref']||'A1:A1'),meetings=[];for(let r=1;r<=range.e.r+1;r++){const number=Number(ws[`A${r}`]?.v);if(!number||number<100)continue;const m=blankMeeting(number,dateText(ws[`B${r}`]?.v||''));m.theme=clean(ws[`C${r}`]?.v);m.word=clean(ws[`D${r}`]?.v);const keys=['receptionist','saa','president','tme','timer','ahCounter','grammarian','varietyMaster','topicsmaster','ge','evaluatorOfEvaluator','evaluatorOfTopicsmaster'];keys.forEach((k,i)=>m.roles[k]=clean(ws[XLSX.utils.encode_cell({r:r-1,c:4+i})]?.v));const starts=[16,20,24,28,32];starts.forEach(c=>{const name=clean(ws[XLSX.utils.encode_cell({r:r-1,c})]?.v),title=clean(ws[XLSX.utils.encode_cell({r:r-1,c:c+1})]?.v),level=clean(ws[XLSX.utils.encode_cell({r:r-1,c:c+2})]?.v),evaluator=clean(ws[XLSX.utils.encode_cell({r:r-1,c:c+3})]?.v);if(name||title||evaluator)m.speakers.push(makeSpeaker({name,title,level,evaluator}))});m.events=[clean(ws[`AL${r}`]?.v),clean(ws[`AM${r}`]?.v)];normalizeMeeting(m);meetings.push(m)}if(!meetings.length)throw new Error('工作安排表中找不到有效場次');detectLegacyTemplates(wb,meetings);applyAgendaSettings(wb,meetings);const memberWs=wb.Sheets['例會人員名單'];let members=[];if(memberWs){const rr=XLSX.utils.decode_range(memberWs['!ref']||'A1:A1');for(let r=1;r<=rr.e.r+1;r++){const name=clean(memberWs[`A${r}`]?.v);if(name&&!/name|姓名/i.test(name))members.push(name)}}const all=[...members,...meetings.flatMap(m=>[...Object.values(m.roles),...m.speakers.flatMap(s=>[s.name,s.evaluator])])].filter(Boolean);members=[...new Set(all)];return normalizeProject({id,fileName,meetings,baseMeetings:clone(meetings),members,assets:readAssets(wb)})}

function excelDateText(v){if(!v)return'';if(v instanceof Date)return formatLocalDate(v);if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:String(v)}return dateText(v)}
function parseTableWorkbook(wb,ws,fileName,id){const rows=XLSX.utils.sheet_to_json(ws,{defval:''}),meetings=[];for(const r of rows){const number=Number(r.MeetingNumber);if(!number)continue;const m=blankMeeting(number,excelDateText(r.MeetingDate));m.theme=clean(r.Theme);m.word=clean(r.Word);const map={receptionist:'Receptionist',saa:'SAA',president:'President',tme:'Toastmaster',timer:'Timer',ahCounter:'AhCounter',grammarian:'Grammarian',varietyMaster:'VarietyMaster',topicsmaster:'Topicsmaster',ge:'GeneralEvaluator',evaluatorOfEvaluator:'EvaluatorOfEvaluator',evaluatorOfTopicsmaster:'EvaluatorOfTopicsmaster'};for(const [k,h] of Object.entries(map))m.roles[k]=clean(r[h]);for(let i=1;i<=5;i++){const s=makeSpeaker({name:r['Speaker'+i],title:r['Title'+i],level:r['LevelProject'+i],evaluator:r['Evaluator'+i]});if([s.name,s.title,s.level,s.evaluator].some(Boolean))m.speakers.push(s)}m.events=[clean(r.Event1),clean(r.Event2)];meetings.push(normalizeMeeting(m))}if(!meetings.length)throw Error('工作安排中沒有可用的 Meeting 資料。');applyAgendaSettings(wb,meetings);const memberName=wb.SheetNames.find(x=>x.includes('例會人員名單')),memberRows=memberName?XLSX.utils.sheet_to_json(wb.Sheets[memberName],{header:1,defval:''}):[],members=memberRows.slice(1).map(r=>clean(r[0])).filter(Boolean).map(name=>({name,active:true}));return normalizeProject({id,fileName,members,meetings,baseMeetings:clone(meetings),assets:readAssets(wb),updatedAt:Date.now()})}
function parseWorkbookV2(buffer,fileName,id){
 const wb=XLSX.read(buffer,{type:'array',cellDates:true,cellFormula:true}),assignmentName=wb.SheetNames.find(x=>x.toLowerCase().includes('assignment for agenda'));
 if(!assignmentName)throw Error('找不到「Assignment for Agenda」工作表。');
 const assignmentSheet=wb.Sheets[assignmentName],a=XLSX.utils.sheet_to_json(assignmentSheet,{header:1,defval:''}),labels=new Map();
 if(clean(a[0]?.[0]).toLowerCase()==='meetingnumber')return parseTableWorkbook(wb,assignmentSheet,fileName,id);
 a.forEach((r,i)=>{const label=clean(r[1]).toLowerCase();if(label)labels.set(label,i)});
 const row=(...names)=>{for(const n of names){const r=labels.get(n.toLowerCase());if(r!=null)return r}return null};
 const get=(c,...names)=>{const r=row(...names);return r==null?'':a[r]?.[c]??''};
 const eventRows=a.map((r,i)=>({i,label:clean(r[1]).toLowerCase()})).filter(x=>['up coming event','upcoming event','up coming event 1','upcoming event 1','up coming event 2','upcoming event 2'].includes(x.label)).map(x=>x.i);
 const meetingRow=row('Meeting number');if(meetingRow==null)throw Error('找不到 Meeting number，檔案格式可能已修改。');
 const meetings=[];
 for(let c=2;c<(a[meetingRow]||[]).length;c++){
  const number=a[meetingRow][c];if(number===''||number==null||Number.isNaN(Number(number)))continue;
  const m=blankMeeting(Math.trunc(Number(number)),excelDateText(get(c,'Date')));m.id='meeting-'+m.number+'-'+c;m.note=clean(a[1]?.[c]||'');m.theme=clean(get(c,'Meeting Theme'));m.word=clean(get(c,'Word of the Day'));
  m.roles.receptionist=clean(get(c,'Receptionist'));m.roles.saa=clean(get(c,'SAA'));m.roles.president=clean(get(c,'President'));m.roles.tme=clean(get(c,'TME'));m.roles.timer=clean(get(c,'Timer'));m.roles.ahCounter=clean(get(c,'Ah Counter'));m.roles.varietyMaster=clean(get(c,'Variety Master'));m.roles.topicsmaster=clean(get(c,'Topicsmaster'));m.roles.ge=clean(get(c,'GE'));m.roles.grammarian=clean(get(c,'Grammarian'));m.roles.evaluatorOfEvaluator=clean(get(c,'Evaluator of Evaluator'));m.roles.evaluatorOfTopicsmaster=clean(get(c,'Evaluator of Topicsmaster'));
  for(let i=1;i<=5;i++){const s=makeSpeaker({name:get(c,'#'+i+' Speaker'),title:get(c,'#'+i+' Title'),level:get(c,'#'+i+' Level'),project:get(c,'#'+i+' Project'),duration:get(c,'#'+i+' Time'),evaluator:get(c,'#'+i+' Evaluator')});if([s.name,s.title,s.level,s.project,s.duration,s.evaluator].some(Boolean))m.speakers.push(s)}
  m.events=[clean(a[eventRows[0]]?.[c]),clean(a[eventRows[1]]?.[c])];meetings.push(normalizeMeeting(m));
 }
 if(!meetings.length)throw Error('檔案中沒有可用的 Meeting 資料。');
 detectLegacyTemplates(wb,meetings);meetings.forEach(normalizeMeeting);applyAgendaSettings(wb,meetings);
 const memberName=wb.SheetNames.find(x=>x.includes('例會人員名單')),memberRows=memberName?XLSX.utils.sheet_to_json(wb.Sheets[memberName],{header:1,defval:''}):[],names=memberRows.slice(1).map(r=>clean(r[1])).filter(Boolean);
 for(const m of meetings)names.push(...Object.values(m.roles),...m.speakers.flatMap(s=>[s.name,s.evaluator]));
 const members=[...new Set(names.map(clean).filter(Boolean))].map(name=>({name,active:true}));
 return normalizeProject({id,fileName,members,meetings,baseMeetings:clone(meetings),assets:readAssets(wb),updatedAt:Date.now()});
}

function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE,{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbPut(value){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function dbGet(id){const db=await openDb();return new Promise((resolve,reject)=>{const req=db.transaction(STORE).objectStore(STORE).get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await dbPut({id:project.id,fileName:project.fileName,updatedAt:Date.now(),project}) ;localStorage.setItem(LAST_KEY,project.id)}catch(e){console.warn('save failed',e)}},250)}
async function fingerprint(file){const data=await file.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',data);return{id:[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,24),data}}
async function importFile(file){if(!file)return;try{const {id,data}=await fingerprint(file),fresh=parseWorkbook(data,file.name,id);const saved=await dbGet(id);project=saved?.project?normalizeProject(saved.project):fresh;if(!project.baseMeetings?.length)project.baseMeetings=clone(fresh.meetings);activeIndex=0;undoStack=[];redoStack=[];localStorage.setItem(LAST_KEY,id);await dbPut({id,fileName:file.name,updatedAt:Date.now(),project});renderAll();toast(saved?'已載入上次編排進度':'Excel 已匯入，可開始編排')}catch(e){console.error(e);toast(e.message||'Excel 匯入失敗',true)}finally{$('#excelFile').value=''}}
async function resumeLast(){try{const id=localStorage.getItem(LAST_KEY);if(!id)return false;const saved=await dbGet(id);if(!saved?.project)return false;project=normalizeProject(saved.project);activeIndex=0;renderAll();toast('已恢復上次編排進度');return true}catch{return false}}

function cloneLayout(source,number,date){const m=blankMeeting(number,date);m.templateId=source.templateId;m.header=clone(source.header);m.sessions=clone(source.sessions);const idMap={};m.sessions.forEach(s=>{const old=s.id;s.id=uid('ses');idMap[old]=s.id;s.subrows.forEach(r=>r.id=uid('sub'))});m.speakers=[];normalizeMeeting(m);return m}
function createMeeting(source=null){const current=activeMeeting(),number=Math.max(...project.meetings.map(m=>Number(m.number)||0),current.number||0)+1,date=inferredMeetingDate(number)||stepClubMeetingDate(current.date||formatLocalDate(new Date()));applyChange(()=>{const m=source?cloneLayout(source,number,date):blankMeeting(number,date);project.meetings.push(m);activeIndex=project.meetings.length-1})}
async function deleteCurrentMeeting(){if(project.meetings.length===1)return;if(!await confirmAction('刪除場次','這會刪除目前場次的編排資料。'))return;applyChange(()=>{project.meetings.splice(activeIndex,1);activeIndex=Math.max(0,activeIndex-1)})}
async function resetCurrentMeeting(){if(!await confirmAction('重設目前場次','將還原匯入 Excel 時的資料；新增場次則恢復空白。'))return;applyChange(()=>{const m=activeMeeting(),base=project.baseMeetings.find(x=>x.number===m.number);project.meetings[activeIndex]=base?clone(base):blankMeeting(m.number,m.date)})}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',2800)}
function confirmAction(title,message){return new Promise(resolve=>{const dlg=$('#confirmDialog');$('#confirmTitle').textContent=title;$('#confirmText').textContent=message;const close=v=>{dlg.close();resolve(v)};$('#confirmOk').onclick=()=>close(true);$('#confirmCancel').onclick=()=>close(false);dlg.oncancel=e=>{e.preventDefault();close(false)};dlg.showModal()})}

function exportWorkbook(){try{syncLegacy(activeMeeting());const wb=XLSX.utils.book_new(),members=XLSX.utils.aoa_to_sheet([['Name'],...project.members.map(x=>[x])]);XLSX.utils.book_append_sheet(wb,members,'例會人員名單');const head=['MeetingNumber','MeetingDate','Theme','Word','Receptionist','SAA','President','Toastmaster','Timer','AhCounter','Grammarian','VarietyMaster','Topicsmaster','GeneralEvaluator','EvaluatorOfEvaluator','EvaluatorOfTopicsmaster'];for(let i=1;i<=5;i++)head.push('Speaker'+i,'Title'+i,'LevelProject'+i,'Evaluator'+i);head.push('Event1','Event2');const rows=[head];for(const m of orderedMeetings()){const r=[m.number,m.date,m.theme,m.word,m.roles.receptionist,m.roles.saa,m.roles.president,m.roles.tme,m.roles.timer,m.roles.ahCounter,m.roles.grammarian,m.roles.varietyMaster,m.roles.topicsmaster,m.roles.ge,m.roles.evaluatorOfEvaluator,m.roles.evaluatorOfTopicsmaster];for(let i=0;i<5;i++){const s=m.speakers[i]||{};r.push(s.name||'',s.title||'',[s.level,s.project].filter(Boolean).join(' - '),s.evaluator||'')}r.push(m.events[0]||'',m.events[1]||'');rows.push(r)}XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'Assignment for Agenda(工作安排)');const settings=orderedMeetings().map(m=>({SchemaVersion:2,MeetingNumber:m.number,TemplateID:m.templateId,HeaderJSON:JSON.stringify(m.header),SessionsJSON:JSON.stringify(m.sessions),SessionOrder:JSON.stringify(m.order),TimeSettings:JSON.stringify(legacyTimesFrom(m)),SpeakerMinutes:JSON.stringify(m.speakers.map(s=>s.minutes)),SpeakerSessionMap:JSON.stringify(m.speakers.map(s=>s.sessionId))}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(settings),'Agenda設定');const assetRows=[];for(const a of Object.values(project.assets||{})){const b64=(a.data||'').split(',')[1]||'';for(let i=0;i<b64.length;i+=30000)assetRows.push({AssetID:a.id,Name:a.name,Mime:a.mime,ChunkIndex:i/30000,Chunk:b64.slice(i,i+30000)})}if(assetRows.length)XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(assetRows),'Agenda資源');XLSX.writeFile(wb,(project.fileName||'SYTC_Agenda').replace(/\.xls[xm]?$/i,'')+'_新版.xlsx');toast('新版 Excel 已下載')}catch(e){console.error(e);toast('Excel 匯出失敗',true)}}

function switchMeeting(direction){const ordered=orderedMeetings(),i=ordered.findIndex(m=>m.id===activeMeeting().id),target=ordered[i+direction];if(target){activeIndex=project.meetings.findIndex(m=>m.id===target.id);renderAll()}}
function selectMeetingNumber(value){const m=project.meetings.find(x=>String(x.number)===String(value));if(m){activeIndex=project.meetings.indexOf(m);renderAll()}}
function commitMeetingNumber(){const value=Math.max(1,Math.round(Number($('#meetingNumberInput').value)||0));if(!value){renderMeetingSelector();return}const found=project.meetings.find(x=>x.number===value);if(found){activeIndex=project.meetings.indexOf(found);renderAll();return}applyChange(()=>{activeMeeting().number=value;if(!activeMeeting().date)activeMeeting().date=inferredMeetingDate(value)})}
function bindUi(){$('#excelFile').addEventListener('change',e=>importFile(e.target.files[0]));$('#importTrigger').onclick=()=>$('#excelFile').click();$('#resumeBtn').onclick=resumeLast;$('#exportBtn').onclick=exportWorkbook;$('#printBtn').onclick=()=>window.print();$('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#prevMeeting').onclick=()=>switchMeeting(-1);$('#nextMeeting').onclick=()=>switchMeeting(1);$('#meetingNumberInput').onchange=commitMeetingNumber;$('#meetingNumberInput').onkeydown=e=>{if(e.key==='Enter')commitMeetingNumber()};$('#addMeeting').onclick=()=>createMeeting();$('#duplicateMeeting').onclick=()=>createMeeting(activeMeeting());$('#deleteMeeting').onclick=deleteCurrentMeeting;$('#resetMeeting').onclick=resetCurrentMeeting;window.addEventListener('resize',scheduleAlignment);window.addEventListener('beforeprint',()=>document.body.classList.add('printing'));window.addEventListener('afterprint',()=>document.body.classList.remove('printing'))}
function exportWorkbookV2(){const members=project.members;project.members=members.filter(x=>x.active).map(x=>x.name);try{exportWorkbook()}finally{project.members=members}}
parseWorkbook=parseWorkbookV2;
async function bootstrap(){bindUi();if(!await resumeLast()){project=demoProject();renderAll()}document.fonts?.ready.then(scheduleAlignment)}
bootstrap();
$('#exportBtn').onclick=exportWorkbookV2;
$('#goMeeting').onclick=commitMeetingNumber;
$$('.tab').forEach(tab=>tab.onclick=()=>{const target=tab.dataset.target;$$('.tab').forEach(x=>x.classList.toggle('active',x===tab));if(target==='preview')$('#preview').scrollIntoView({behavior:'smooth'});else $('#editor').scrollIntoView({behavior:'smooth'})});
